content:
660          }
   661          if (lexer_match(ctx->lexer, LEX_T_ELLIPSIS)) {
   662              if (!lexer_force_int(ctx->lexer, &high)) {
   663                  return false;
   664              }
   665          } else {
   666              high = low;
   667          }
   668
   669          if (!lexer_force_match(ctx->lexer, LEX_T_RSQUARE)) {
   670              return false;
   671          }
   672
   673          if (low > high) {
   674              lexer_error(ctx->lexer, "Invalid bit range %d to %d.", low, high);
   675              return false;
   676          } else if (high >= symbol->width) {
   677              lexer_error(ctx->lexer,
   678                          "Cannot select bits %d to %d of %d-bit field %s.",
   679                          low, high, symbol->width, symbol->name);
   680              return false;
   681          } else if (symbol->level == EXPR_L_NOMINAL
   682                     && (low != 0 || high != symbol->width - 1)) {
   683              lexer_error(ctx->lexer,
   684                          "Cannot select subfield of nominal field %s.",
   685                          symbol->name);
   686              return false;
   687          }
   688
   689          f->ofs = low;
   690          f->n_bits = high - low + 1;
   691      } else {
   692          f->ofs = 0;
   693          f->n_bits = symbol->width;
   694      }
   695
   696      return true;
   697  }
