   699  static bool
   700  parse_relop(struct expr_context *ctx, enum expr_relop *relop)
   701  {
   702      if (expr_relop_from_token(ctx->lexer->token.type, relop)) {
   703          lexer_get(ctx->lexer);
   704          return true;
   705      } else {
   706          lexer_syntax_error(ctx->lexer, "expecting relational operator");
   707          return false;
   708      }
   709  }
