   711  static bool
   712  assign_constant_set_type(struct expr_context *ctx,
   713                           struct expr_constant_set *cs,
   714                           enum expr_constant_type type)
   715  {
   716      if (!cs->n_values || cs->type == type) {
   717          cs->type = type;
   718          return true;
   719      } else {
   720          lexer_syntax_error(ctx->lexer, "expecting %s",
   721                             cs->type == EXPR_C_INTEGER ? "integer" : "string");
   722          return false;
   723      }
   724  }
   725
   726  static bool
   727  parse_addr_sets(struct expr_context *ctx, struct expr_constant_set *cs,
   728                  size_t *allocated_values)
   729  {
   730      struct expr_constant_set *addr_sets
   731          = (ctx->addr_sets
   732             ? shash_find_data(ctx->addr_sets, ctx->lexer->token.s)
   733             : NULL);
   734      if (!addr_sets) {
   735          lexer_syntax_error(ctx->lexer, "expecting address set name");
   736          return false;
   737      }
   738
   739      if (!assign_constant_set_type(ctx, cs, EXPR_C_INTEGER)) {
   740          return false;
   741      }
   742
   743      size_t n_values = cs->n_values + addr_sets->n_values;
   744      if (n_values >= *allocated_values) {
   745          cs->values = xrealloc(cs->values, n_values * sizeof *cs->values);
   746          *allocated_values = n_values;
   747      }
   748      for (size_t i = 0; i < addr_sets->n_values; i++) {
   749          cs->values[cs->n_values++] = addr_sets->values[i];
   750      }
   751
   752      return true;
   753  }
   754
   755  static bool
   756  parse_port_group(struct expr_context *ctx, struct expr_constant_set *cs,
   757                   size_t *allocated_values)
   758  {
   759      struct expr_constant_set *port_group
   760          = (ctx->port_groups
   761             ? shash_find_data(ctx->port_groups, ctx->lexer->token.s)
   762             : NULL);
   763      if (!port_group) {
   764          lexer_syntax_error(ctx->lexer, "expecting port group name");
   765          return false;
   766      }
   767
   768      if (!assign_constant_set_type(ctx, cs, EXPR_C_STRING)) {
   769          return false;
   770      }
   771
   772      size_t n_values = cs->n_values + port_group->n_values;
   773      if (n_values >= *allocated_values) {
   774          cs->values = xrealloc(cs->values, n_values * sizeof *cs->values);
   775          *allocated_values = n_values;
   776      }
   777      for (size_t i = 0; i < port_group->n_values; i++) {
   778          cs->values[cs->n_values++].string =
   779              xstrdup(port_group->values[i].string);
   780      }
   781
   782      return true;
   783  }
   784
   785  static bool
   786  parse_constant(struct expr_context *ctx, struct expr_constant_set *cs,
   787                 size_t *allocated_values)
   788  {
   789      if (cs->n_values >= *allocated_values) {
   790          cs->values = x2nrealloc(cs->values, allocated_values,
   791                                  sizeof *cs->values);
   792      }
   793
   794      if (ctx->lexer->token.type == LEX_T_STRING) {
   795          if (!assign_constant_set_type(ctx, cs, EXPR_C_STRING)) {
   796              return false;
   797          }
   798          cs->values[cs->n_values++].string = xstrdup(ctx->lexer->token.s);
   799          lexer_get(ctx->lexer);
   800          return true;
   801      } else if (ctx->lexer->token.type == LEX_T_INTEGER ||
   802                 ctx->lexer->token.type == LEX_T_MASKED_INTEGER) {
   803          if (!assign_constant_set_type(ctx, cs, EXPR_C_INTEGER)) {
   804              return false;
   805          }
   806
   807          union expr_constant *c = &cs->values[cs->n_values++];
   808          c->value = ctx->lexer->token.value;
   809          c->format = ctx->lexer->token.format;
   810          c->masked = ctx->lexer->token.type == LEX_T_MASKED_INTEGER;
   811          if (c->masked) {
   812              c->mask = ctx->lexer->token.mask;
   813          }
   814          lexer_get(ctx->lexer);
   815          return true;
   816      } else if (ctx->lexer->token.type == LEX_T_MACRO) {
   817          if (!parse_addr_sets(ctx, cs, allocated_values)) {
   818              return false;
   819          }
   820          lexer_get(ctx->lexer);
   821          return true;
   822      } else if (ctx->lexer->token.type == LEX_T_PORT_GROUP) {
   823          if (!parse_port_group(ctx, cs, allocated_values)) {
   824              return false;
   825          }
   826          lexer_get(ctx->lexer);
   827          return true;
   828      } else {
   829          lexer_syntax_error(ctx->lexer, "expecting constant");
   830          return false;
   831      }
   832  }
   833
   834  /* Parses a single or {}-enclosed set of integer or string constants into 'cs',
   835   * which the caller need not have initialized.  Returns true on success, in
   836   * which case the caller owns 'cs', false on failure, in which case 'cs' is
   837   * indeterminate. */
   838  static bool
   839  parse_constant_set(struct expr_context *ctx, struct expr_constant_set *cs)
   840  {
   841      size_t allocated_values = 0;
   842      bool ok;
   843
   844      memset(cs, 0, sizeof *cs);
   845      if (lexer_match(ctx->lexer, LEX_T_LCURLY)) {
   846          ok = true;
   847          cs->in_curlies = true;
   848          do {
   849              if (!parse_constant(ctx, cs, &allocated_values)) {
   850                  ok = false;
   851                  break;
   852              }
   853              lexer_match(ctx->lexer, LEX_T_COMMA);
   854          } while (!lexer_match(ctx->lexer, LEX_T_RCURLY));
   855      } else {
   856          ok = parse_constant(ctx, cs, &allocated_values);
   857      }
   858      if (!ok) {
   859          expr_constant_set_destroy(cs);
   860      }
   861      return ok;
   862  }
   863
   864  /* Parses from 'lexer' a single integer or string constant compatible with the
   865   * type of 'f' into 'c'.
   866   *
   867   * Returns true if successful, false if an error occurred.  Upon return,
   868   * returns true if and only if lexer->error is NULL.  On failure, 'c' is
   869   * indeterminate. */
   870  bool
   871  expr_constant_parse(struct lexer *lexer, const struct expr_field *f,
   872                      union expr_constant *c)
   873  {
   874      if (lexer->error) {
   875          return false;
   876      }
   877
   878      struct expr_context ctx = { .lexer = lexer };
   879
   880      struct expr_constant_set cs;
   881      memset(&cs, 0, sizeof cs);
   882      size_t allocated_values = 0;
   883      if (parse_constant(&ctx, &cs, &allocated_values)
   884          && type_check(&ctx, f, &cs)) {
   885          *c = cs.values[0];
   886          cs.n_values = 0;
   887      }
   888      expr_constant_set_destroy(&cs);
   889
   890      return !lexer->error;
   891  }
   892
   893  /* Appends to 's' a re-parseable representation of constant 'c' with the given
   894   * 'type'. */
   895  void
   896  expr_constant_format(const union expr_constant *c,
   897                       enum expr_constant_type type, struct ds *s)
   898  {
   899      if (type == EXPR_C_STRING) {
   900          json_string_escape(c->string, s);
   901      } else {
   902          struct lex_token token;
   903          token.type = c->masked ? LEX_T_MASKED_INTEGER : LEX_T_INTEGER;
   904          token.s = NULL;
   905          token.format = c->format;
   906          token.value = c->value;
   907          if (c->masked) {
   908              token.mask = c->mask;
   909          }
   910
   911          lex_token_format(&token, s);
   912      }
   913  }
   914
   915  /* Frees the contents of 'c', which has the specified 'type'.
   916   *
   917   * Does not free(c). */
   918  void
   919  expr_constant_destroy(const union expr_constant *c,
   920                        enum expr_constant_type type)
   921  {
   922      if (c && type == EXPR_C_STRING) {
   923          free(c->string);
   924      }
   925  }
   926
   927  /* Parses from 'lexer' a single or {}-enclosed set of at least one integer or
   928   * string constants into 'cs', which the caller need not have initialized.
   929   *
   930   * Returns true if successful, false if an error occurred.  Upon return,
   931   * returns true if and only if lexer->error is NULL.  On failure, 'cs' is
   932   * indeterminate. */
   933  bool
   934  expr_constant_set_parse(struct lexer *lexer, struct expr_constant_set *cs)
   935  {
   936      if (!lexer->error) {
   937          struct expr_context ctx = { .lexer = lexer };
   938          parse_constant_set(&ctx, cs);
   939      }
   940      return !lexer->error;
   941  }
   942
   943  /* Appends to 's' a re-parseable representation of 'cs'. */
   944  void
   945  expr_constant_set_format(const struct expr_constant_set *cs, struct ds *s)
   946  {
   947      bool curlies = cs->in_curlies || cs->n_values != 1;
   948      if (curlies) {
   949          ds_put_char(s, '{');
   950      }
   951
   952      for (const union expr_constant *c = cs->values;
   953           c < &cs->values[cs->n_values]; c++) {
   954          if (c != cs->values) {
   955              ds_put_cstr(s, ", ");
   956          }
   957
   958          expr_constant_format(c, cs->type, s);
   959      }
   960
   961      if (curlies) {
   962          ds_put_char(s, '}');
   963      }
   964  }
   965
   966  void
   967  expr_constant_set_destroy(struct expr_constant_set *cs)
   968  {
   969      if (cs) {
   970          if (cs->type == EXPR_C_STRING) {
   971              for (size_t i = 0; i < cs->n_values; i++) {
   972                  free(cs->values[i].string);
   973              }
   974          }
   975          free(cs->values);
   976      }
   977  }
